javascript:!function(){document.querySelectorAll('user-query, .query-text, [data-test-id="user-query"]'),document.querySelectorAll('model-response, .model-response-text, [data-test-id="model-response"]');let e=`# Gemini Chat Export\n*Exported on: ${(new Date).toLocaleString()}*\n\n---\n\n`;const n=document.querySelectorAll("message-content, .conversation-container, .user-query-container");if(0===n.length){const n=Array.from(document.querySelectorAll("user-query, .query-text-content")),t=Array.from(document.querySelectorAll("model-response, .response-container-content")),r=Math.max(n.length,t.length);for(let o=0;o<r;o++)if(n[o]&&(e+=`### User\n${n[o].innerText.trim()}\n\n`),t[o]){let n=t[o].innerText.trim();e+=`#### Gemini\n${n}\n\n---\n\n`}}else n.forEach(n=>{const t=n.matches("user-query")||n.closest("user-query")||n.classList.contains("user-query-container"),r=n.innerText.trim();e+=t?`### User\n${r}\n\n`:`#### Gemini\n${r}\n\n---\n\n`});const t=new Blob([e],{type:"text/markdown"}),r=URL.createObjectURL(t),o=document.createElement("a");o.href=r,o.download=`gemini-chat-${(new Date).toISOString().slice(0,10)}.md`,document.body.appendChild(o),o.click(),document.body.removeChild(o),URL.revokeObjectURL(r)}();
